import { Paper, Slide, useMediaQuery } from '@mui/material'
import { useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import type { ActionDefinition } from '../../../data/action_types'
import type { ActionRun } from '../../../services/actions/action_run_registry'
import type { ActionRunSettingsStore } from '../../../services/actions/action_run_settings_service'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import type { ActionConversationStore } from '../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../run/state/action_history_store'
import { currentActionPromptDraft, runPopupAction } from '../run/popup/action_popup_operations'
import { ActionPhraseButtons } from './action_phrase_buttons'
import type { ActionRunInputStore } from '../run/state/action_run_input_store'
import type { ActionRunResultStore } from '../run/state/action_run_result_store'
import { useActionRunSettings } from '../shared/use_action_run_settings'

interface ActionPhraseButtonsOwnerProps {
    action: ActionDefinition
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    settingsStore: ActionRunSettingsStore
}

function selectActiveRunStatus(run: ActionRun | null) {
    if (run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput') return run.status

    return null
}

/** Owns follow-up visibility and phrase actions. */
export function ActionPhraseButtonsOwner(props: ActionPhraseButtonsOwnerProps) {
    const { action, context, conversationStore, historyStore, inputStore, resultStore, runValidationError, settingsStore } = props
    const activeRunStatus = useActionRunSelector(action.id, context, selectActiveRunStatus)
    const hasUnresolvedApprovals = useActionRunSelector(action.id, context, (run) => !!run?.approvals.length)
    const conversationSnapshot = useSyncExternalStore(
        conversationStore.subscribe,
        conversationStore.getSnapshot,
        conversationStore.getSnapshot,
    )
    const reduceMotion = useMediaQuery('(prefers-reduced-motion: reduce)')
    const settings = useActionRunSettings(action, settingsStore)
    const waitingForInput = activeRunStatus === 'waitingForInput'
        || (activeRunStatus === null
            && !conversationSnapshot.loading
            && conversationSnapshot.selectedConversation?.status === 'waitingForInput')
    if (action.type !== 'agent' || action.phrases.length === 0) return null

    const handleSelect = (text: string) => {
        const promptDraft = currentActionPromptDraft(action, context, false)
        promptDraft.replace(text)
        inputStore.setConvertMessage(null)
    }
    const handleDoubleClick = (text: string) => {
        handleSelect(text)
        void runPopupAction({
            action,
            context,
            conversationStore,
            historyStore,
            inputStore,
            resultStore,
            runValidationError,
            settings,
            settingsStore,
        })
    }

    return (
        <Slide direction="up" in={waitingForInput && !hasUnresolvedApprovals} mountOnEnter timeout={reduceMotion ? 0 : undefined} unmountOnExit>
            <Paper
                elevation={4}
                sx={{
                    bgcolor: 'background.paper',
                    border: 1,
                    borderColor: 'divider',
                    borderRadius: 1,
                    flexShrink: 0,
                    mx: 1,
                    mb: 1,
                    p: 1,
                }}
            >
                <ActionPhraseButtons onDoubleClick={handleDoubleClick} onSelect={handleSelect} phrases={action.phrases} />
            </Paper>
        </Slide>
    )
}

import { Button, Stack } from '@mui/material'
import type { MouseEvent } from 'react'
import type { ActionPhrase } from '../../../data/action_types'
import { dialogService } from '../../../services/dialog_service'
import { actionPhraseLabel } from './action_phrase_label'

interface ActionPhraseButtonsProps {
    onDoubleClick: (text: string) => void
    onSelect: (text: string) => void
    phrases: ActionPhrase[]
}

/** Quick follow-up controls shown once an agent conversation can continue. */
export function ActionPhraseButtons(props: ActionPhraseButtonsProps) {
    const { onDoubleClick, onSelect, phrases } = props

    const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
        try {
            const text = event.currentTarget.dataset.phraseText
            if (text === undefined) throw new Error('Missing predefined phrase text')
            onSelect(text)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Predefined phrase could not be selected' })
        }
    }

    const handleDoubleClick = (event: MouseEvent<HTMLButtonElement>) => {
        try {
            const text = event.currentTarget.dataset.phraseText
            if (text === undefined) throw new Error('Missing predefined phrase text')
            onDoubleClick(text)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Predefined phrase could not be submitted' })
        }
    }

    return (
        <Stack aria-label="Predefined phrases" direction="row" role="group" sx={{ flexWrap: 'wrap', gap: 1 }}>
            {phrases.map(({ text, title }, index) => (
                <Button
                    data-phrase-text={text}
                    key={`${index}-${title}-${text}`}
                    onClick={handleClick}
                    onDoubleClick={handleDoubleClick}
                    size="small"
                    variant="outlined"
                >
                    {actionPhraseLabel(title, text)}
                </Button>
            ))}
        </Stack>
    )
}

import { useCallback, useEffect, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import type { ActionDefinition } from '../../../data/action_types'
import type { ActionRun } from '../../../services/actions/action_run_registry'
import type { ActionRunSettingsStore } from '../../../services/actions/action_run_settings_service'
import { dialogService } from '../../../services/dialog_service'
import { remoteConnectionService } from '../../../services/data/remote_connection_service'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import { ActionAgentPrompt } from './action_agent_prompt'
import type { ActionConversationStore } from '../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../run/state/action_history_store'
import { currentActionPromptDraft, runPopupAction } from '../run/popup/action_popup_operations'
import { actionPopupRunDisabled } from '../run/popup/action_popup_run_disabled'
import type { ActionRunInputStore } from '../run/state/action_run_input_store'
import type { ActionRunResultStore } from '../run/state/action_run_result_store'
import type { ActionScheduleStore } from '../run/schedule/action_schedule_store'
import { defaultPreparePrompt } from '../run/popup/action_popup_defaults'
import { ActionPopupBottomRow } from '../run/popup/action_popup_bottom_row'
import type { ActionUsageScopeStore } from '../run/popup/action_usage_scope_store'
import { useActionRunSettings } from '../shared/use_action_run_settings'
import { ActionPhraseButtonsOwner } from '../editor/action_phrase_buttons_owner'

interface ActionAgentPromptOwnerProps {
    action: ActionDefinition
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    scheduleStore: ActionScheduleStore
    settingsStore: ActionRunSettingsStore
    usageScopeStore: ActionUsageScopeStore
}

function selectSessionActive(run: ActionRun | null) {
    return run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
}

/** Owns prompt draft binding, preparation, and keyboard-run behavior. */
export function ActionAgentPromptOwner(props: ActionAgentPromptOwnerProps) {
    const {
        action, context, conversationStore, historyStore, inputStore, resultStore, runValidationError,
        scheduleStore, settingsStore, usageScopeStore,
    } = props
    const sessionActive = useActionRunSelector(action.id, context, selectSessionActive)
    const activeActionType = useActionRunSelector(action.id, context, (run) => run?.activeActionType ?? null)
    const interactionReady = useActionRunSelector(action.id, context, (run) => !!run?.interactionReady)
    const runStatus = useActionRunSelector(action.id, context, (run) => run?.status ?? 'idle')
    const conversationSnapshot = useSyncExternalStore(
        conversationStore.subscribe,
        conversationStore.getSnapshot,
        conversationStore.getSnapshot,
    )
    const inputSnapshot = useSyncExternalStore(inputStore.subscribe, inputStore.getSnapshot, inputStore.getSnapshot)
    const remoteConnection = useSyncExternalStore(
        remoteConnectionService.subscribe,
        remoteConnectionService.getSnapshot,
        remoteConnectionService.getSnapshot,
    )
    const settings = useActionRunSettings(action, settingsStore)
    const prepare = action.type === 'agent'
        && !sessionActive
        && runStatus !== 'completed'
        && conversationSnapshot.selectedConversation === null
    const promptDraft = currentActionPromptDraft(action, context, prepare)
    const handleAttachments = useCallback(async (files: File[], insertMarkdown: (markdown: string) => void) => {
        const attachmentWorkflow = await import('../../../services/attachments/attachment_workflow')
        if (context.file) {
            await attachmentWorkflow.attachFilesToCardMarkdown(context.file, files, insertMarkdown)
            return
        }

        await attachmentWorkflow.attachFilesToOriginalMarkdown(files, insertMarkdown)
    }, [context])
    const attachmentHandler = action.type === 'agent' ? handleAttachments : undefined

    useEffect(() => {
        if (!prepare || promptDraft.hasLocalEdits()) return
        if (remoteConnection.status === 'connecting' || remoteConnection.status === 'reconnecting') return

        void promptDraft.prepare(() => defaultPreparePrompt(action, context)).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: 'Could not prepare action prompt' })
        })
    }, [action, context, prepare, promptDraft, remoteConnection.status])

    const handleRunShortcut = () => {
        const prompt = promptDraft.getSnapshot()
        const runState = {
            agentActive: sessionActive && activeActionType === 'agent',
            interactionReady,
            runDisabledMessage: settings.runDisabledMessage,
            runStatus,
        }
        if (actionPopupRunDisabled(
            action,
            runState,
            prompt,
            promptDraft.getEditorSnapshot().preparationStatus,
        )) return

        const operationInput = {
            action,
            context,
            conversationStore,
            historyStore,
            inputStore,
            resultStore,
            runValidationError,
            settings,
            settingsStore,
        }
        void runPopupAction(operationInput)
    }

    return (
        <ActionAgentPrompt
            attachmentHandler={attachmentHandler}
            bottomRow={action.type === 'agent' || activeActionType === 'agent' ? (
                <ActionPopupBottomRow
                    action={action}
                    assignmentContext={context}
                    conversationStore={conversationStore}
                    embedded
                    historyStore={historyStore}
                    inputStore={inputStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    scheduleStore={scheduleStore}
                    settingsStore={settingsStore}
                    usageScopeStore={usageScopeStore}
                />
            ) : undefined}
            convertMessage={inputSnapshot.convertMessage}
            onRunShortcut={handleRunShortcut}
            promptDraft={promptDraft}
            responsePrompts={(
                <ActionPhraseButtonsOwner
                    action={action}
                    context={context}
                    conversationStore={conversationStore}
                    historyStore={historyStore}
                    inputStore={inputStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    settingsStore={settingsStore}
                />
            )}
        />
    )
}

